async function loadUser(id: string): Promise<any> {
  const res = await fetch('/api/users/' + id);
  if (!res.ok) {
    throw new Error('bad status ' + res.status);
  }
  const user = await res.json();

  const orgRes = await fetch('/api/orgs/' + user.orgId);
  if (!orgRes.ok) {
    throw new Error('bad status ' + orgRes.status);
  }
  user.org = await orgRes.json();

  return user;
}

async function loadUsers(ids: string[]): Promise<any[]> {
  const results = await Promise.all(
    ids.map(async (id) => {
      try {
        return { id, user: await loadUser(id) };
      } catch (err) {
        throw err;
      }
    })
  );

  return results.map((r) => r.user);
}

module.exports = { loadUser, loadUsers };
